part of '../isar/main_db.dart';

enum CCFilter {
  all,
  available,
  frozen;

  @override
  String toString() {
    if (this == all) {
      return "Show $name outputs";
    }

    return "${name.capitalize()} outputs";
  }
}

/// Keep only utxos whose otherData contains [key] (or only those
/// without it), e.g. PIVX shield note rows vs transparent outputs.
typedef UtxoTagFilter = ({String key, bool present});

enum CCSortDescriptor {
  age,
  address,
  value;

  @override
  String toString() {
    switch (this) {
      case CCSortDescriptor.age:
        return "Confirmations";
      case CCSortDescriptor.address:
        return "Address";
      case CCSortDescriptor.value:
        return "Amount";
    }
  }
}

/// Sorts [utxos] by [sort] in the given direction. Confirmations go
/// by block height, unconfirmed outputs counting as the fewest.
List<UTXO> _sortedUtxos(
  List<UTXO> utxos,
  CCSortDescriptor sort,
  bool ascending,
) {
  int compare(UTXO a, UTXO b) {
    switch (sort) {
      case CCSortDescriptor.age:
        // Fewer confirmations = higher (or no) block height.
        final ha = a.blockHeight ?? 1 << 62;
        final hb = b.blockHeight ?? 1 << 62;
        return hb.compareTo(ha);
      case CCSortDescriptor.address:
        return (a.address ?? "").compareTo(b.address ?? "");
      case CCSortDescriptor.value:
        return a.value.compareTo(b.value);
    }
  }

  return utxos..sort((a, b) => ascending ? compare(a, b) : compare(b, a));
}

extension MainDBQueries on MainDB {
  List<Id> queryUTXOsSync({
    required String walletId,
    required CCFilter filter,
    required CCSortDescriptor sort,
    required String searchTerm,
    required CryptoCurrency cryptoCurrency,
    UtxoTagFilter? tagFilter,
    bool? ascending,
  }) {
    var preSort = getUTXOs(walletId).filter().group((q) {
      final qq = q.group(
        (q) => q.usedIsNull().or().usedEqualTo(false),
      );
      switch (filter) {
        case CCFilter.frozen:
          return qq.and().isBlockedEqualTo(true);
        case CCFilter.available:
          return qq.and().isBlockedEqualTo(false);
        case CCFilter.all:
          return qq;
      }
    });

    if (tagFilter != null) {
      preSort = tagFilter.present
          ? preSort.and().otherDataContains(tagFilter.key)
          : preSort.and().group(
              (q) => q
                  .otherDataIsNull()
                  .or()
                  .not()
                  .otherDataContains(tagFilter.key),
            );
    }

    if (searchTerm.isNotEmpty) {
      preSort = preSort.and().group(
        (q) {
          var qq = q.addressContains(searchTerm, caseSensitive: false);

          qq = qq.or().nameContains(searchTerm, caseSensitive: false);
          qq = qq.or().group(
                (q) => q
                    .isBlockedEqualTo(true)
                    .and()
                    .blockedReasonContains(searchTerm, caseSensitive: false),
              );

          qq = qq.or().txidContains(searchTerm, caseSensitive: false);
          qq = qq.or().blockHashContains(searchTerm, caseSensitive: false);

          final maybeDecimal = Decimal.tryParse(searchTerm);
          if (maybeDecimal != null) {
            qq = qq.or().valueEqualTo(
                  Amount.fromDecimal(
                    maybeDecimal,
                    fractionDigits: cryptoCurrency.fractionDigits,
                  ).raw.toInt(),
                );
          }

          final maybeInt = int.tryParse(searchTerm);
          if (maybeInt != null) {
            qq = qq.or().valueEqualTo(maybeInt);
          }

          return qq;
        },
      );
    }

    if (ascending != null) {
      return _sortedUtxos(preSort.findAllSync(), sort, ascending)
          .map((e) => e.id)
          .toList();
    }

    final List<Id> ids;
    switch (sort) {
      case CCSortDescriptor.age:
        ids = preSort.sortByBlockHeight().idProperty().findAllSync();
        break;
      case CCSortDescriptor.address:
        ids = preSort.sortByAddress().idProperty().findAllSync();
        break;
      case CCSortDescriptor.value:
        ids = preSort.sortByValueDesc().idProperty().findAllSync();
        break;
    }
    return ids;
  }

  Map<String, List<Id>> queryUTXOsGroupedByAddressSync({
    required String walletId,
    required CCFilter filter,
    required CCSortDescriptor sort,
    required String searchTerm,
    required CryptoCurrency cryptoCurrency,
    UtxoTagFilter? tagFilter,
    bool? ascending,
  }) {
    var preSort = getUTXOs(walletId).filter().group((q) {
      final qq = q.group(
        (q) => q.usedIsNull().or().usedEqualTo(false),
      );
      switch (filter) {
        case CCFilter.frozen:
          return qq.and().isBlockedEqualTo(true);
        case CCFilter.available:
          return qq.and().isBlockedEqualTo(false);
        case CCFilter.all:
          return qq;
      }
    });

    if (tagFilter != null) {
      preSort = tagFilter.present
          ? preSort.and().otherDataContains(tagFilter.key)
          : preSort.and().group(
              (q) => q
                  .otherDataIsNull()
                  .or()
                  .not()
                  .otherDataContains(tagFilter.key),
            );
    }

    if (searchTerm.isNotEmpty) {
      preSort = preSort.and().group(
        (q) {
          var qq = q.addressContains(searchTerm, caseSensitive: false);

          qq = qq.or().nameContains(searchTerm, caseSensitive: false);
          qq = qq.or().group(
                (q) => q
                    .isBlockedEqualTo(true)
                    .and()
                    .blockedReasonContains(searchTerm, caseSensitive: false),
              );

          qq = qq.or().txidContains(searchTerm, caseSensitive: false);
          qq = qq.or().blockHashContains(searchTerm, caseSensitive: false);

          final maybeDecimal = Decimal.tryParse(searchTerm);
          if (maybeDecimal != null) {
            qq = qq.or().valueEqualTo(
                  Amount.fromDecimal(
                    maybeDecimal,
                    fractionDigits: cryptoCurrency.fractionDigits,
                  ).raw.toInt(),
                );
          }

          final maybeInt = int.tryParse(searchTerm);
          if (maybeInt != null) {
            qq = qq.or().valueEqualTo(maybeInt);
          }

          return qq;
        },
      );
    }

    final List<UTXO> utxos;
    switch (ascending != null ? null : sort) {
      case null:
        utxos = _sortedUtxos(preSort.findAllSync(), sort, ascending!);
        break;
      case CCSortDescriptor.age:
        utxos = preSort.sortByBlockHeight().findAllSync();
        break;
      case CCSortDescriptor.address:
        utxos = preSort.sortByAddress().findAllSync();
        break;
      case CCSortDescriptor.value:
        utxos = preSort.sortByValueDesc().findAllSync();
        break;
    }

    final Map<String, List<Id>> results = {};
    for (final utxo in utxos) {
      if (results[utxo.address!] == null) {
        results[utxo.address!] = [];
      }
      results[utxo.address!]!.add(utxo.id);
    }

    return results;
  }
}
